<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';require dirname(__DIR__,2).'/app/autoload.php';
use FMonitor2\InstallationProcess\JobsSchemaMigration;use FMonitor2\Jobs\{MariaDbJobQueue,MariaDbOperatorJobs,MariaDbOutbox,OutboxDeliveryHandler,OutboxDispatchScheduler};
assertSameValue(true,class_exists(OutboxDeliveryHandler::class)&&class_exists(MariaDbOperatorJobs::class),'INTENTIONAL_RED: full outbox delivery/manual recovery seams exist');
$host=getenv('FMONITOR_TEST_DB_HOST')?:'127.0.0.1';$port=(int)(getenv('FMONITOR_TEST_DB_PORT')?:23306);$user=getenv('FMONITOR_TEST_DB_ADMIN_USER')?:'root';$password=getenv('FMONITOR_TEST_DB_ADMIN_PASSWORD')?:'fmonitor2_test_root_local';$name='t_outbox_lifecycle_'.bin2hex(random_bytes(5));$admin=new mysqli($host,$user,$password,'',$port);$admin->query("CREATE DATABASE `{$name}` DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");$db=new mysqli($host,$user,$password,$name,$port);$p='delivery_';$now='2026-09-09T10:00:00.000000Z';$tokens=array_map(static fn(int$i):string=>str_repeat(dechex($i),64),range(1,12));
try{JobsSchemaMigration::apply($db,$p);$queue=new MariaDbJobQueue($db,$p,static function()use(&$now):string{return$now;},static function()use(&$tokens):string{return array_shift($tokens);},['outbox.dispatch'=>[1]]);$outbox=new MariaDbOutbox($db,$p,static function()use(&$now):string{return$now;});$sweep=new OutboxDispatchScheduler($outbox,$queue);$db->begin_transaction();$intent=$outbox->append(['eventId'=>'event-recover','channel'=>'email','template'=>'approved-v1','version'=>1,'data'=>['objectId'=>7]]);$db->commit();$sweep->enqueuePending();
    $calls=[];$transport=static function(array$message)use(&$calls):array{$calls[]=$message;return count($calls)<=5?['status'=>'ambiguous_retryable','failureCode'=>'TRANSPORT_TIMEOUT']:['status'=>'delivered','providerReference'=>'provider-ok'];};$handler=new OutboxDeliveryHandler($outbox,$transport,static function()use(&$now):string{return$now;});$lease=$queue->claim(['workerId'=>'delivery-worker','batch'=>1])[0];for($attempt=1;$attempt<=5;$attempt++){$outcome=$handler->handle($lease);assertSameValue('ambiguous_retryable',$outcome['status'],"ambiguous attempt {$attempt}");$failed=$queue->fail(['jobId'=>$lease['jobId'],'leaseToken'=>$lease['leaseToken'],'failureCode'=>'TRANSPORT_TIMEOUT','retryable'=>true]);if($attempt<5){$now=$failed['availableAtUtc'];$lease=$queue->claim(['workerId'=>'delivery-worker','batch'=>1])[0];}}assertSameValue('dead',$failed['status'],'fifth ambiguous generic attempt is dead');assertSameValue('pending',$db->query("SELECT status FROM `{$p}fm2_outbox_intents` WHERE intent_id=".(int)$intent['intentId'])->fetch_column(),'ambiguous exhaustion preserves committed pending intent for operator recovery');
    $operator=new MariaDbOperatorJobs($db,$p,static fn(string$a):bool=>$a==='deployment-operator');$retry=$operator->retry(['authority'=>'deployment-operator','jobId'=>$lease['jobId'],'operationId'=>'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','nowUtc'=>$now]);assertSameValue('created',$retry['status'],'operator creates linked dispatch retry job');$retryLease=$queue->claim(['workerId'=>'delivery-worker','batch'=>1])[0];assertSameValue([1,$lease['jobId']],[(int)$retryLease['attempt'],(int)$db->query("SELECT retry_of_job_id FROM `{$p}fm2_jobs` WHERE job_id=".(int)$retryLease['jobId'])->fetch_column()],'linked job restarts generic attempt1 with provenance');$delivered=$handler->handle($retryLease);assertSameValue('delivered',$delivered['status'],'linked retry can deliver same intent');$deliveredCalls=count($calls);$deliveredRows=(int)$db->query("SELECT COUNT(*)n FROM `{$p}fm2_outbox_attempt_events`")->fetch_assoc()['n'];assertSameValue($delivered,$handler->handle($retryLease),'lost response before queue completion replays durable delivered result');assertSameValue([$deliveredCalls,$deliveredRows],[count($calls),(int)$db->query("SELECT COUNT(*)n FROM `{$p}fm2_outbox_attempt_events`")->fetch_assoc()['n']],'delivered replay before queue complete has zero transport/event');$queue->complete(['jobId'=>$retryLease['jobId'],'leaseToken'=>$retryLease['leaseToken'],'result'=>['status'=>'delivered']]);assertSameValue($delivered,$handler->handle($retryLease),'stale invocation after queue completion still reads durable delivered result');assertSameValue([$deliveredCalls,$deliveredRows],[count($calls),(int)$db->query("SELECT COUNT(*)n FROM `{$p}fm2_outbox_attempt_events`")->fetch_assoc()['n']],'delivered replay after queue complete has zero transport/event');assertSameValue('delivered',$db->query("SELECT status FROM `{$p}fm2_outbox_intents` WHERE intent_id=".(int)$intent['intentId'])->fetch_column(),'intent becomes delivered');$attemptRows=$db->query("SELECT job_id,attempt,idempotency_reference FROM `{$p}fm2_outbox_attempt_events` WHERE intent_id=".(int)$intent['intentId'].' ORDER BY attempt_event_id')->fetch_all(MYSQLI_ASSOC);assertSameValue(6,count($attemptRows),'five dead-cycle attempts plus linked success retained');assertSameValue(2,count(array_unique(array_column($attemptRows,'job_id'))),'attempt history distinguishes original and linked job cycles');assertSameValue(1,count(array_unique(array_column($attemptRows,'idempotency_reference'))),'provider idempotency stays intent-wide across manual retry');
    $db->begin_transaction();$permanentIntent=$outbox->append(['eventId'=>'event-permanent','channel'=>'email','template'=>'approved-v1','version'=>1,'data'=>['objectId'=>8]]);$db->commit();$sweep->enqueuePending();$permanentLease=$queue->claim(['workerId'=>'delivery-worker','batch'=>1])[0];$permanentCalls=0;$permanentHandler=new OutboxDeliveryHandler($outbox,static function(array$m)use(&$permanentCalls):array{$permanentCalls++;return['status'=>'permanent','failureCode'=>'RECIPIENT_INVALID'];},static function()use(&$now):string{return$now;});$permanent=$permanentHandler->handle($permanentLease);assertSameValue(['permanent','RECIPIENT_INVALID'],[$permanent['status'],$permanent['failureCode']],'permanent transport result explicit');$permanentRows=(int)$db->query("SELECT COUNT(*)n FROM `{$p}fm2_outbox_attempt_events`")->fetch_assoc()['n'];assertSameValue($permanent,$permanentHandler->handle($permanentLease),'permanent result replays before queue fail');assertSameValue([1,$permanentRows],[$permanentCalls,(int)$db->query("SELECT COUNT(*)n FROM `{$p}fm2_outbox_attempt_events`")->fetch_assoc()['n']],'permanent pre-fail replay no transport/event');$queue->fail(['jobId'=>$permanentLease['jobId'],'leaseToken'=>$permanentLease['leaseToken'],'failureCode'=>'RECIPIENT_INVALID','retryable'=>false]);assertSameValue($permanent,$permanentHandler->handle($permanentLease),'permanent result replays after queue fail');assertSameValue([1,$permanentRows],[$permanentCalls,(int)$db->query("SELECT COUNT(*)n FROM `{$p}fm2_outbox_attempt_events`")->fetch_assoc()['n']],'permanent post-fail replay no transport/event');assertSameValue('dead',$db->query("SELECT status FROM `{$p}fm2_outbox_intents` WHERE intent_id=".(int)$permanentIntent['intentId'])->fetch_column(),'permanent delivery makes intent dead without business rollback');$deadRows=(int)$db->query("SELECT COUNT(*)n FROM `{$p}fm2_outbox_attempt_events`")->fetch_assoc()['n'];$malicious=$queue->enqueue(['jobType'=>'outbox.dispatch','payloadVersion'=>1,'payload'=>['intentId'=>$permanentIntent['intentId']],'availableAtUtc'=>$now,'idempotencyKey'=>'dddddddd-dddd-4ddd-8ddd-dddddddddddd','actor'=>['type'=>'system','id'=>'unlinked-producer']]);$maliciousLease=$queue->claim(['workerId'=>'delivery-worker','batch'=>1])[0];$maliciousCalls=0;$maliciousHandler=new OutboxDeliveryHandler($outbox,static function(array$m)use(&$maliciousCalls):array{$maliciousCalls++;return['status'=>'delivered'];},static function()use(&$now):string{return$now;});$refused=$maliciousHandler->handle($maliciousLease);assertSameValue(['permanent','OUTBOX_INTENT_DEAD'],[$refused['status'],$refused['failureCode']],'unlinked dispatch cannot revive dead intent');assertSameValue([0,$deadRows,'dead'],[$maliciousCalls,(int)$db->query("SELECT COUNT(*)n FROM `{$p}fm2_outbox_attempt_events`")->fetch_assoc()['n'],$db->query("SELECT status FROM `{$p}fm2_outbox_intents` WHERE intent_id=".(int)$permanentIntent['intentId'])->fetch_column()],'unlinked dead-intent dispatch has zero transport/attempt/status mutation');$queue->fail(['jobId'=>$maliciousLease['jobId'],'leaseToken'=>$maliciousLease['leaseToken'],'failureCode'=>'OUTBOX_INTENT_DEAD','retryable'=>false]);$permanentRetry=$operator->retry(['authority'=>'deployment-operator','jobId'=>$permanentLease['jobId'],'operationId'=>'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','nowUtc'=>$now]);assertSameValue('created',$permanentRetry['status'],'operator can explicitly retry permanent dead dispatch job');$permanentRetryLease=$queue->claim(['workerId'=>'delivery-worker','batch'=>1])[0];$recoveryCalls=0;$recoveryHandler=new OutboxDeliveryHandler($outbox,static function(array$m)use(&$recoveryCalls):array{$recoveryCalls++;return['status'=>'delivered','providerReference'=>'provider-recovered'];},static function()use(&$now):string{return$now;});assertSameValue('delivered',$recoveryHandler->handle($permanentRetryLease)['status'],'linked retry recovers permanent dead intent');assertSameValue(1,$recoveryCalls,'permanent recovery invokes transport once');$queue->complete(['jobId'=>$permanentRetryLease['jobId'],'leaseToken'=>$permanentRetryLease['leaseToken'],'result'=>['status'=>'delivered']]);assertSameValue('delivered',$db->query("SELECT status FROM `{$p}fm2_outbox_intents` WHERE intent_id=".(int)$permanentIntent['intentId'])->fetch_column(),'manual linked retry moves dead intent to delivered');echo"PASS: DURABLE-BACKGROUND-JOBS-001 outbox terminal delivery and manual recovery\n";
}finally{$db->close();$admin->query("DROP DATABASE IF EXISTS `{$name}`");$admin->close();}


